use dioxus::prelude::*;
use dioxus_i18n::t;

use crate::i18n::use_init_i18n_from_browser;

// Generated by `dx` before every wasm build; host builds (tests, clippy) never have it.
#[cfg(target_arch = "wasm32")]
const TAILWIND_CSS: Option<Asset> = Some(asset!("/assets/tailwind.css"));
#[cfg(not(target_arch = "wasm32"))]
const TAILWIND_CSS: Option<Asset> = None;

#[component]
pub fn App() -> Element {
    use_init_i18n_from_browser();

    rsx! {
        if let Some(href) = TAILWIND_CSS {
            document::Stylesheet { href }
        }
        div { class: "flex min-h-screen flex-col bg-slate-50 text-gray-800 dark:bg-slate-950 dark:text-slate-200",
            header { class: "flex items-center gap-2 border-b border-slate-200 bg-white px-4 py-3 dark:border-slate-800 dark:bg-slate-900",
                span { class: "inline-block size-3 rounded-sm bg-indigo-600 dark:bg-indigo-400" }
                span { class: "font-bold text-gray-900 dark:text-white", {t!("app-name")} }
            }
            main { class: "flex flex-1 items-center justify-center p-6",
                p { class: "text-sm text-slate-500 dark:text-slate-400", {t!("app-tagline")} }
            }
        }
    }
}
